module color_code_generator (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [1:0] n,\n    input wire [3:0] p_mask,\n    output reg [3:0] output_value,\n    output reg output_valid,\n    output reg done\n);\n\n    // State encoding\n    localparam [2:0] IDLE      = 3'd0;\n    localparam [2:0] INIT      = 3'd1;\n    localparam [2:0] SEARCH    = 3'd2;\n    localparam [2:0] OUTPUT    = 3'd3;\n    localparam [2:0] COMPLETE  = 3'd4;\n    \n    reg [2:0] state, next_state;\n    reg [3:0] current_value;\n    reg [3:0] counter;\n    reg [15:0] visited;\n    reg [3:0] search_idx;\n    reg found_next;\n    reg [3:0] next_candidate;\n    \n    // Cycle counter to prevent infinite search\n    reg [7:0] cycle_count;\n    localparam [7:0] MAX_CYCLES = 8'd100;\n    \n    // Hamming distance function\n    function [3:0] hamming;\n        input [3:0] a;\n        input [3:0] b;\n        integer i;\n        begin\n            hamming = 4'd0;\n            for (i = 0; i < 4; i = i + 1) begin\n                if (a[i] != b[i]) hamming = hamming + 4'd1;\n            end\n        end\n    endfunction\n    \n    // Allowed distance check\n    function is_allowed;\n        input [3:0] dist;\n        input [3:0] mask;\n        begin\n            is_allowed = (dist >= 4'd1) && (dist <= 4'd4) && mask[dist-4'd1];\n        end\n    endfunction\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            current_value <= 4'd0;\n            counter <= 4'd0;\n            visited <= 16'd0;\n            search_idx <= 4'd0;\n            found_next <= 1'b0;\n            next_candidate <= 4'd0;\n            output_value <= 4'd0;\n            output_valid <= 1'b0;\n            done <= 1'b0;\n            cycle_count <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    output_valid <= 1'b0;\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= INIT;\n                        cycle_count <= 8'd0;\n                    end\n                end\n                \n                INIT: begin\n                    current_value <= 4'd0;\n                    counter <= 4'd0;\n                    visited <= 16'd1;  // Mark 0 as visited\n                    output_valid <= 1'b0;\n                    \n                    if (n == 2'd0 || n > 2'd3) begin  // Invalid n\n                        state <= COMPLETE;\n                    end else begin\n                        state <= OUTPUT;\n                    end\n                end\n                \n                OUTPUT: begin\n                    output_value <= current_value;\n                    output_valid <= 1'b1;\n                    counter <= counter + 4'd1;\n                    \n                    if (counter == (4'd1 << n) - 4'd1) begin\n                        state <= COMPLETE;\n                    end else begin\n                        state <= SEARCH;\n                        search_idx <= 4'd0;\n                        found_next <= 1'b0;\n                        cycle_count <= 8'd0;\n                    end\n                end\n                \n                SEARCH: begin\n                    output_valid <= 1'b0;\n                    cycle_count <= cycle_count + 8'd1;\n                    \n                    if (search_idx < (4'd1 << n) && !found_next) begin\n                        if (!visited[search_idx]) begin\n                            if (is_allowed(hamming(current_value, search_idx), p_mask)) begin\n                                found_next <= 1'b1;\n                                next_candidate <= search_idx;\n                            end\n                        end\n                        search_idx <= search_idx + 4'd1;\n                    end\n                    \n                    if (found_next || cycle_count >= MAX_CYCLES || search_idx >= (4'd1 << n)) begin\n                        if (found_next) begin\n                            visited[next_candidate] <= 1'b1;\n                            current_value <= next_candidate;\n                            state <= OUTPUT;\n                        end else begin\n                            state <= COMPLETE;\n                        end\n                    end\n                end\n                \n                COMPLETE: begin\n                    output_valid <= 1'b0;\n                    done <= 1'b1;\n                    if (!start) state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule